/**
 * The program itself: parse `--key`, `--iv` and `--data`, encrypt the data one
 * AES-CBC block at a time, and print each ciphertext block.
 *
 * This is a port of `test17.py`, and it reproduces that program's observable
 * behaviour exactly — including its failure modes.  When the reference program
 * dies on an unhandled `ValueError`, so does this one, with the same traceback
 * and the same exit status; the line numbers below are the ones CPython would
 * report for the original source.
 */

import { ArgumentParser } from './python/argparse.mjs';
import { bytesRepr, encodeUtf8 } from './python/bytes.mjs';
import { formatTraceback, PythonError, SystemExit } from './python/errors.mjs';
import { AESModeOfOperationCBC } from './aes/index.mjs';
import { BLOCK_SIZE } from './aes/block-cipher.mjs';

/**
 * Program name used in usage, help and error messages.  The reference build is
 * a frozen binary, so this is the name it reports rather than `test17.py`.
 */
export const PROG = 'test17_executable';

/** Name the frozen reference binary uses in its crash banner. */
const SCRIPT_STEM = 'test17';

/** Frames of `test17.py` that appear in a traceback, keyed by failing step. */
const SCRIPT_FRAMES = {
  buildCipher: [
    ['test17.py', 27, '<module>'],
    ['test17.py', 12, 'main'],
  ],
  encryptBlock: [
    ['test17.py', 27, '<module>'],
    ['test17.py', 19, 'main'],
  ],
};

/**
 * Run `fn`, tagging anything it raises with the script frames that led here so
 * the traceback can be rebuilt at the top level.
 *
 * @template T
 * @param {import('./python/errors.mjs').PyFrame[]} frames script frames, outermost first
 * @param {() => T} fn the step to run
 * @returns {T} whatever `fn` returned
 */
function traced(frames, fn) {
  try {
    return fn();
  } catch (error) {
    error.scriptFrames = frames;
    throw error;
  }
}

/**
 * The body of the original `main()`.
 *
 * @param {string[]} argv command-line tokens, program name excluded
 * @param {import('./python/argparse.mjs').ParserIO} io output sinks
 * @throws {SystemExit} when argument parsing prints help or an error
 * @throws {PythonError} on any of the reference program's runtime failures
 */
export function main(argv, io) {
  const parser = new ArgumentParser({ prog: PROG, io });
  parser.addArgument(['--key'], { required: true }); // 16 bytes key
  parser.addArgument(['--iv'], { required: true }); // 16 bytes IV
  parser.addArgument(['--data'], { required: true }); // 48 bytes data (3 blocks)
  const args = parser.parseArgs(argv);

  // Encrypt multiple blocks with CBC
  const aes = traced(
    SCRIPT_FRAMES.buildCipher,
    () => new AESModeOfOperationCBC(encodeUtf8(args.key), encodeUtf8(args.iv)),
  );
  const data = encodeUtf8(args.data);

  // Encrypt each block, letting CBC chain them together
  const ciphertexts = [];
  for (let i = 0; i < data.length; i += BLOCK_SIZE) {
    const block = data.subarray(i, i + BLOCK_SIZE);
    const cipher = traced(SCRIPT_FRAMES.encryptBlock, () => aes.encrypt(block));
    ciphertexts.push(cipher);
  }

  // Print all ciphertexts
  for (const cipher of ciphertexts) {
    io.writeOut(`${bytesRepr(cipher)}\n`);
  }
}

/**
 * Run the program and report the exit status, translating an unhandled
 * exception into the traceback and crash banner the frozen reference binary
 * writes to stderr.
 *
 * @param {string[]} argv command-line tokens, program name excluded
 * @param {import('./python/argparse.mjs').ParserIO} io output sinks
 * @param {number} pid process id used in the crash banner
 * @returns {number} the process exit status
 */
export function run(argv, io, pid) {
  try {
    main(argv, io);
    return 0;
  } catch (error) {
    if (error instanceof SystemExit) return error.code;
    if (error instanceof PythonError) {
      io.writeErr(formatTraceback(error, error.scriptFrames ?? []));
      io.writeErr(
        `[PYI-${pid}:ERROR] Failed to execute script '${SCRIPT_STEM}' ` +
          'due to unhandled exception!\n',
      );
      return 1;
    }
    throw error;
  }
}

/**
 * A small re-implementation of the subset of Python's `argparse` this program
 * uses: optional arguments with a single value, `-h/--help`, required-argument
 * checking, prefix abbreviation, and `argparse`'s exact usage/help/error text.
 *
 * The behaviour reproduced here is `argparse`'s, not a simplification of it —
 * including the parts that surprise people, such as `-5` being accepted as a
 * value while `-5x` is not, `--` surviving into the unrecognised-arguments
 * list, and the missing-required check firing before that list is reported.
 */

import { SystemExit } from './errors.mjs';

/** `argparse` treats a bare `-1` or `-1.5` as a value, not an option. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Column budget `argparse` assumes when it cannot see a real terminal. */
const DEFAULT_WIDTH = 80;

/** Indentation step used by the help formatter. */
const INDENT_INCREMENT = 2;

/** Upper bound on how far right the help column may start. */
const MAX_HELP_POSITION = 24;

/**
 * One declared command-line option.
 *
 * @typedef {object} Action
 * @property {string[]} optionStrings e.g. `['-h', '--help']`
 * @property {string} dest attribute the parsed value lands on
 * @property {number} nargs number of values the option consumes (0 or 1)
 * @property {boolean} required whether omitting it is an error
 * @property {string} metavar placeholder shown in usage and help
 * @property {string} help one-line description, empty for none
 * @property {'store'|'help'} kind what the option does when seen
 */

/**
 * A token recognised as an option, plus however its value was attached.
 *
 * @typedef {object} OptionTuple
 * @property {Action|null} action the matched option, or `null` if unknown
 * @property {string} optionString the flag as matched, e.g. `'--key'`
 * @property {'='|''|null} sep how a value was attached: `'='` for `--key=v`,
 *   `''` for a short option's glued-on tail, `null` for no attached value
 * @property {string|null} explicitArg the attached value, if any
 */

/**
 * The parsed-argument container `parse_args` returns.  Values are exposed as
 * plain properties, keyed by each option's `dest`.
 */
export class Namespace {
  /** @param {Record<string, unknown>} values initial attribute values */
  constructor(values = {}) {
    Object.assign(this, values);
  }
}

/**
 * Everything a parser needs in order to talk to the outside world.  Injecting
 * it keeps the parser testable and keeps process-level concerns in one place.
 *
 * @typedef {object} ParserIO
 * @property {(text: string) => void} writeOut write to standard output
 * @property {(text: string) => void} writeErr write to standard error
 */

/** A command-line parser modelled on `argparse.ArgumentParser`. */
export class ArgumentParser {
  /**
   * @param {object} [options]
   * @param {string} [options.prog] program name shown in usage and errors
   * @param {ParserIO} [options.io] output sinks; defaults to the real streams
   */
  constructor({ prog = 'prog', io } = {}) {
    /** @type {string} */
    this.prog = prog;
    /** @type {ParserIO} */
    this.io = io ?? {
      writeOut: (text) => process.stdout.write(text),
      writeErr: (text) => process.stderr.write(text),
    };
    /** @type {Action[]} */
    this.actions = [];
    /** @type {Map<string, Action>} */
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      kind: 'help',
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * Declare an option, mirroring `parser.add_argument`.
   *
   * @param {string[]} optionStrings the flags that select this option
   * @param {object} [config]
   * @param {'store'|'help'} [config.kind] what seeing the option does
   * @param {number} [config.nargs] values consumed (0 or 1)
   * @param {boolean} [config.required] whether it must be supplied
   * @param {string} [config.metavar] placeholder for usage/help text
   * @param {string} [config.help] one-line description
   * @param {unknown} [config.defaultValue] value used when absent
   * @returns {Action} the created action
   */
  addArgument(optionStrings, config = {}) {
    const {
      kind = 'store',
      nargs = 1,
      required = false,
      help = '',
      defaultValue = null,
    } = config;

    // argparse derives dest from the first long option, or the first short one.
    const longOption = optionStrings.find((option) => option.startsWith('--'));
    const dest = (longOption ?? optionStrings[0]).replace(/^-+/, '').replace(/-/g, '_');
    const metavar = config.metavar ?? dest.toUpperCase();

    /** @type {Action} */
    const action = { optionStrings, dest, nargs, required, metavar, help, kind, defaultValue };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /* ----------------------------------------------------------------- usage */

  /**
   * @param {Action} action the option to render
   * @returns {string} how the option appears inside the usage line
   */
  formatActionUsage(action) {
    const [first] = action.optionStrings;
    const body = action.nargs === 0 ? first : `${first} ${action.metavar}`;
    return action.required ? body : `[${body}]`;
  }

  /** @returns {string} the `usage: ...` line, newline terminated */
  formatUsage() {
    const parts = this.actions.map((action) => this.formatActionUsage(action));
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  /**
   * @param {Action} action the option to render
   * @returns {string} how the option appears in the options list
   */
  formatActionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
  }

  /** @returns {string} the full `--help` text, newline terminated */
  formatHelp() {
    const invocations = this.actions.map((action) => this.formatActionInvocation(action));
    const longest = Math.max(...invocations.map((text) => text.length));

    // argparse: help_position = min(action_max_length + 2, max_help_position),
    // where action_max_length already includes the section indent.
    const maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(DEFAULT_WIDTH - 2 - 20, INDENT_INCREMENT * 2),
    );
    const helpPosition = Math.min(longest + INDENT_INCREMENT + 2, maxHelpPosition);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;

    let text = `${this.formatUsage()}\noptions:\n`;
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      const indent = ' '.repeat(INDENT_INCREMENT);
      if (!action.help) {
        text += `${indent}${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        text += `${indent}${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        text += `${indent}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return text;
  }

  /* ---------------------------------------------------------------- exiting */

  /**
   * Print the usage line and an error message to stderr, then exit with
   * status 2 — `argparse`'s behaviour for any malformed command line.
   *
   * @param {string} message the error detail
   * @returns {never}
   */
  error(message) {
    this.io.writeErr(this.formatUsage());
    this.io.writeErr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  /**
   * Print the help text to stdout and exit successfully.
   *
   * @returns {never}
   */
  printHelpAndExit() {
    this.io.writeOut(this.formatHelp());
    throw new SystemExit(0);
  }

  /* --------------------------------------------------------------- parsing */

  /**
   * The name `argparse` uses for an option in error messages: every one of its
   * flags, joined with a slash.  So `--data` reports as `--data`, but the help
   * option reports as `-h/--help` whichever flag was actually typed.
   *
   * @param {Action} action the option
   * @returns {string} the name to show
   */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  /**
   * Classify one token, the way `argparse._parse_optional` does.
   *
   * `sep` records how the value was attached: `'='` for `--opt=value`, `''` for
   * a short option's glued-on tail as in `-xvalue`, and `null` when there is no
   * attached value.  The three cases are not interchangeable — `-h=1` is an
   * error while `-h1` is not — so the distinction has to survive.
   *
   * @param {string} token a raw command-line token
   * @returns {OptionTuple|null} `null` when the token is a value, not an option
   */
  parseOptional(token) {
    if (token === '' || !token.startsWith('-')) return null;

    const exact = this.optionStringActions.get(token);
    if (exact) return { action: exact, optionString: token, sep: null, explicitArg: null };

    if (token.length === 1) return null; // a bare '-' is a value

    const separator = token.indexOf('=');
    if (separator !== -1) {
      const optionString = token.slice(0, separator);
      const action = this.optionStringActions.get(optionString);
      if (action) {
        return { action, optionString, sep: '=', explicitArg: token.slice(separator + 1) };
      }
    }

    const candidates = this.getOptionTuples(token);
    if (candidates.length > 1) {
      const matches = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (candidates.length === 1) return candidates[0];

    // No option matched. A bare negative number is a value, since no declared
    // option looks like one, and neither is anything containing a space;
    // otherwise this is an unknown option.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, sep: null, explicitArg: null };
  }

  /**
   * Find the declared options a token could stand for.
   *
   * Long options may be abbreviated to any unambiguous prefix.  Short options
   * may not be abbreviated at all, but they may carry their value glued on, so
   * only the token's first two characters are considered.
   *
   * @param {string} token a raw command-line token starting with `-`
   * @returns {OptionTuple[]} one entry per candidate option
   */
  getOptionTuples(token) {
    const tuples = [];

    if (token.startsWith('--')) {
      const separator = token.indexOf('=');
      const prefix = separator === -1 ? token : token.slice(0, separator);
      const sep = separator === -1 ? null : '=';
      const explicitArg = separator === -1 ? null : token.slice(separator + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          tuples.push({ action, optionString, sep, explicitArg });
        }
      }
      return tuples;
    }

    const shortOption = token.slice(0, 2);
    const action = this.optionStringActions.get(shortOption);
    if (action) {
      tuples.push({ action, optionString: shortOption, sep: '', explicitArg: token.slice(2) });
    }
    return tuples;
  }

  /**
   * How many following tokens an option consumes, given the classification
   * pattern that starts where its values would.
   *
   * An option's value must be a plain value: `argparse` strips `-` from the
   * match pattern for optionals, so `--` can never be swallowed as one.
   *
   * @param {Action} action the option being satisfied
   * @param {string} pattern the remaining pattern, e.g. `'AOA'`
   * @returns {number} the number of tokens to consume
   */
  matchArgument(action, pattern) {
    if (action.nargs === 0) return 0;
    if (pattern.startsWith('A')) return 1;
    return this.error(
      `argument ${ArgumentParser.actionName(action)}: expected one argument`,
    );
  }

  /**
   * Classify every token as an option (`'O'`), a value (`'A'`), or the `--`
   * separator (`'-'`).  Everything after the first `--` is a value.
   *
   * @param {string[]} argv command-line tokens
   * @returns {{pattern: string[], optionTuples: Map<number, OptionTuple>}}
   */
  classify(argv) {
    /** @type {string[]} */
    const pattern = [];
    /** @type {Map<number, OptionTuple>} */
    const optionTuples = new Map();
    let afterSeparator = false;

    argv.forEach((token, index) => {
      if (!afterSeparator && token === '--') {
        afterSeparator = true;
        pattern.push('-');
        return;
      }
      if (afterSeparator) {
        pattern.push('A');
        return;
      }
      const tuple = this.parseOptional(token);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, tuple);
        pattern.push('O');
      }
    });

    return { pattern, optionTuples };
  }

  /**
   * Consume the option at `startIndex`, along with its value and — for a short
   * option carrying a tail, as in `-xyz` — any further options glued to it.
   *
   * @param {string[]} argv command-line tokens
   * @param {string[]} pattern per-token classification from {@link classify}
   * @param {OptionTuple} tuple the option found at `startIndex`
   * @param {number} startIndex index of the option token
   * @param {Namespace} namespace where parsed values are stored
   * @param {Set<Action>} seen actions encountered so far
   * @param {string[]} extras collector for unrecognised tokens
   * @returns {number} the index to resume parsing at
   */
  consumeOptional(argv, pattern, tuple, startIndex, namespace, seen, extras) {
    let { action, optionString, sep, explicitArg } = tuple;
    if (action === null) {
      extras.push(argv[startIndex]);
      return startIndex + 1;
    }

    /** @type {[Action, string|null][]} */
    const pending = [];
    let stop = startIndex + 1;

    for (;;) {
      if (explicitArg === null) {
        const argCount = this.matchArgument(action, pattern.slice(startIndex + 1).join(''));
        stop = startIndex + 1 + argCount;
        pending.push([action, argCount === 1 ? argv[startIndex + 1] : null]);
        break;
      }

      const argCount = this.matchArgument(action, 'A');

      if (argCount === 0 && optionString[1] !== '-' && explicitArg !== '') {
        // A short option that takes no value, with a tail glued on: peel the
        // next short option off the tail, since `-xyz` means `-x -y -z`.  An
        // `=` was an explicit request to pass a value, and a tail starting with
        // a prefix character cannot be an option name, so neither can chain.
        if (sep || explicitArg.startsWith('-')) {
          this.error(
            `argument ${ArgumentParser.actionName(action)}: ` +
              `ignored explicit argument '${explicitArg}'`,
          );
        }
        pending.push([action, null]);
        const prefixChar = optionString[0];
        const nextOptionString = prefixChar + explicitArg[0];
        const nextAction = this.optionStringActions.get(nextOptionString);
        if (nextAction === undefined) {
          extras.push(prefixChar + explicitArg);
          stop = startIndex + 1;
          break;
        }
        action = nextAction;
        optionString = nextOptionString;
        const tail = explicitArg.slice(1);
        if (tail === '') {
          sep = null;
          explicitArg = null;
        } else if (tail.startsWith('=')) {
          sep = '=';
          explicitArg = tail.slice(1);
        } else {
          sep = '';
          explicitArg = tail;
        }
        continue;
      }

      if (argCount === 1) {
        pending.push([action, explicitArg]);
        stop = startIndex + 1;
        break;
      }

      this.error(
        `argument ${ArgumentParser.actionName(action)}: ` +
          `ignored explicit argument '${explicitArg}'`,
      );
    }

    for (const [pendingAction, value] of pending) {
      seen.add(pendingAction);
      if (pendingAction.kind === 'help') this.printHelpAndExit();
      if (pendingAction.nargs === 1) namespace[pendingAction.dest] = value;
    }
    return stop;
  }

  /**
   * Parse a command line, returning the namespace and any leftover tokens.
   *
   * @param {string[]} argv command-line tokens, program name excluded
   * @returns {[Namespace, string[]]} the namespace and the unrecognised tokens
   */
  parseKnownArgs(argv) {
    const namespace = new Namespace();
    for (const action of this.actions) {
      if (action.kind === 'store') namespace[action.dest] = action.defaultValue;
    }

    const { pattern, optionTuples } = this.classify(argv);

    /** @type {string[]} */
    const extras = [];
    /** @type {Set<Action>} */
    const seen = new Set();
    let index = 0;

    while (index < argv.length) {
      const tuple = optionTuples.get(index);
      if (tuple === undefined) {
        // A value, or a `--`, with no option waiting to consume it.
        extras.push(argv[index]);
        index += 1;
        continue;
      }
      index = this.consumeOptional(
        argv, pattern, tuple, index, namespace, seen, extras,
      );
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * Parse a command line, rejecting anything left over.
   *
   * @param {string[]} argv command-line tokens, program name excluded
   * @returns {Namespace} the parsed arguments
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

