// Token pool + argv-array generator for the differential argparse fuzz.

const V16 = '0123456789abcdef';                                  // 16 chars
const V48 = '};}w]2=?1C++Z+Eabi8?X_Iv2e:cAx^plV%)F%mHpL![!,c)';  // 48 chars

export const POOL = [
  // ---- the real option names
  '--key',
  '--iv',
  '--data',
  // ---- help, exact
  '-h',
  '--help',
  // ---- long-option abbreviations (unambiguous and ambiguous)
  '--k',
  '--ke',
  '--i',
  '--d',
  '--da',
  '--dat',
  '--he',
  '--hel',
  // ---- '=' attached values
  `--key=${V16}`,
  `--iv=${V16}`,
  `--data=${V48}`,
  '--key=',            // explicit empty value
  '--help=1',          // value handed to a nargs=0 option
  '--i=1',
  '--d=1',
  '--da=x',
  '--unknown=1',
  '--data=--key',      // value that looks like an option name
  '--key=--iv',
  // ---- short-option gluing / tails
  '-h=1',
  '-hh',
  '-hx',
  '-h-',
  '-h--',
  '-hkey',
  '-h=',
  '-x',
  '-xh',
  // ---- degenerate prefixes
  '--=x',
  '-=x',
  '---key',
  '--',                // bare separator
  '-',                 // bare dash
  '--0',
  '--unknown',
  '-key',
  '-iv',
  // ---- negative-number-looking tokens
  '-5',
  '-1.5',
  '-.5',
  '-0',
  '-5x',
  // ---- plain values
  'positional',
  '',                  // empty string
  V16,
  V48,
  'value with spaces',
  '-dash value with spaces',
  '--key value with spaces',
];

// Deterministic PRNG (mulberry32) so a run is reproducible from its seed.
export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The full case list: 0-token, every 1-token, every 2-token pair, then
 * `randomCount` uniformly random arrays of length 0..8.
 */
export function buildCases(randomCount = 600, seed = 20260810) {
  const cases = [];
  const seen = new Set();
  const push = (argv, origin) => {
    const key = JSON.stringify(argv);
    if (seen.has(key)) return;
    seen.add(key);
    cases.push({ argv, origin });
  };

  push([], 'exhaustive-0');
  for (const a of POOL) push([a], 'exhaustive-1');
  for (const a of POOL) for (const b of POOL) push([a, b], 'exhaustive-2');

  const rand = rng(seed);
  const pick = () => POOL[Math.floor(rand() * POOL.length)];
  let added = 0;
  let guard = 0;
  while (added < randomCount && guard < randomCount * 50) {
    guard += 1;
    const len = Math.floor(rand() * 9); // 0..8 inclusive
    const argv = [];
    for (let i = 0; i < len; i += 1) argv.push(pick());
    const key = JSON.stringify(argv);
    if (seen.has(key)) continue;
    seen.add(key);
    cases.push({ argv, origin: 'random' });
    added += 1;
  }
  return { cases, randomAdded: added };
}

// Differential fuzz of argument parsing: reference PyInstaller binary vs the
// Node.js port.  Compares stdout bytes, PID-normalised stderr bytes and exit
// codes.  Re-runs both sides up to 3 extra times before believing a mismatch,
// because the reference is flaky under load.

import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { buildCases } from './pool.mjs';

const REF = '/workspace/dataset/test17_executable';
const PORT_ARGS = ['/output/test17.mjs'];
const NODE = process.execPath;
const CONCURRENCY = Number(process.env.FUZZ_CONCURRENCY ?? 8);
const RANDOM_COUNT = Number(process.env.FUZZ_RANDOM ?? 600);
const TIMEOUT_MS = 20000;

// Keep the environment identical and free of anything argparse's help
// formatter would read (COLUMNS changes the wrap width).
const ENV = { ...process.env };
delete ENV.COLUMNS;
delete ENV.LINES;

function exec(cmd, args, argv) {
  return new Promise((resolve) => {
    const child = spawn(cmd, [...args, ...argv], {
      env: ENV,
      cwd: '/tmp',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const out = [];
    const err = [];
    let done = false;
    const timer = setTimeout(() => {
      if (!done) { child.kill('SIGKILL'); }
    }, TIMEOUT_MS);
    child.stdout.on('data', (c) => out.push(c));
    child.stderr.on('data', (c) => err.push(c));
    child.on('error', (e) => {
      done = true;
      clearTimeout(timer);
      resolve({ code: null, signal: null, spawnError: String(e), stdout: Buffer.alloc(0), stderr: Buffer.alloc(0) });
    });
    child.on('close', (code, signal) => {
      done = true;
      clearTimeout(timer);
      resolve({
        code,
        signal,
        stdout: Buffer.concat(out),
        stderr: Buffer.concat(err),
      });
    });
  });
}

const PYI = /\[PYI-\d+:ERROR\]/g;
const normalise = (buf) => Buffer.from(buf.toString('binary').replace(PYI, '[PYI-PID:ERROR]'), 'binary');

function diff(ref, port) {
  const reasons = [];
  if (!ref.stdout.equals(port.stdout)) reasons.push('stdout');
  if (!normalise(ref.stderr).equals(normalise(port.stderr))) reasons.push('stderr');
  if (ref.code !== port.code) reasons.push('exit-code');
  return reasons;
}

// A reference result that looks like the documented flakiness: killed by a
// signal / null status with nothing written.
const refLooksFlaky = (r) =>
  r.spawnError !== undefined ||
  r.code === null ||
  (r.signal !== null && r.signal !== undefined) ||
  (r.code !== 0 && r.code !== 1 && r.code !== 2);

async function runCase(c) {
  let ref = await exec(REF, [], c.argv);
  let port = await exec(NODE, PORT_ARGS, c.argv);
  let reasons = diff(ref, port);
  let attempts = 1;
  const history = [];
  while ((reasons.length > 0 || refLooksFlaky(ref)) && attempts <= 3) {
    history.push({ attempt: attempts, reasons: [...reasons], refCode: ref.code, refSignal: ref.signal, refFlaky: refLooksFlaky(ref) });
    // Re-run the exact same commands, per the flakiness note.
    await new Promise((r) => setTimeout(r, 120 * attempts));
    ref = await exec(REF, [], c.argv);
    port = await exec(NODE, PORT_ARGS, c.argv);
    reasons = diff(ref, port);
    attempts += 1;
    if (reasons.length === 0 && !refLooksFlaky(ref)) break;
  }
  return { ...c, ref, port, reasons, attempts, history, refFlaky: refLooksFlaky(ref) };
}

async function main() {
  const { cases, randomAdded } = buildCases(RANDOM_COUNT);
  process.stderr.write(`cases: ${cases.length} (random arrays: ${randomAdded})\n`);

  const results = new Array(cases.length);
  let next = 0;
  let finished = 0;
  const workers = Array.from({ length: CONCURRENCY }, async () => {
    for (;;) {
      const i = next++;
      if (i >= cases.length) return;
      results[i] = await runCase(cases[i]);
      finished += 1;
      if (finished % 250 === 0) process.stderr.write(`  ...${finished}/${cases.length}\n`);
    }
  });
  await Promise.all(workers);

  const mismatches = results.filter((r) => r.reasons.length > 0);
  const flaky = results.filter((r) => r.reasons.length === 0 && r.attempts > 1);
  const stillWeird = results.filter((r) => r.refFlaky);

  const enc = (b) => b.toString('binary');
  const report = {
    total: results.length,
    matched: results.length - mismatches.length,
    mismatched: mismatches.length,
    recoveredAfterRetry: flaky.length,
    refStillOddStatus: stillWeird.map((r) => ({ argv: r.argv, code: r.ref.code, signal: r.ref.signal })),
    byOrigin: results.reduce((acc, r) => {
      acc[r.origin] = acc[r.origin] ?? { total: 0, mismatched: 0 };
      acc[r.origin].total += 1;
      if (r.reasons.length > 0) acc[r.origin].mismatched += 1;
      return acc;
    }, {}),
    exitCodeHistogram: results.reduce((acc, r) => {
      const k = `${r.ref.code}`;
      acc[k] = (acc[k] ?? 0) + 1;
      return acc;
    }, {}),
    mismatches: mismatches.map((r) => ({
      argv: r.argv,
      origin: r.origin,
      reasons: r.reasons,
      attempts: r.attempts,
      ref: { code: r.ref.code, signal: r.ref.signal, stdout: enc(r.ref.stdout), stderr: enc(normalise(r.ref.stderr)) },
      port: { code: r.port.code, signal: r.port.signal, stdout: enc(r.port.stdout), stderr: enc(normalise(r.port.stderr)) },
    })),
  };
  writeFileSync('/tmp/fuzz-report.json', JSON.stringify(report, null, 2));
  process.stderr.write(`\nDONE total=${report.total} matched=${report.matched} mismatched=${report.mismatched} recovered=${report.recoveredAfterRetry}\n`);
}

main();

